 # Restore genuine default values and source width-selected AUTOINT tokens.
 header=texts['libs/UtilitiesLib/include/utilitieslib/utils/textparser.h'];macros={name:next(line for line in header.splitlines()if line.startswith('#define TOK_'+name+'('))for name in ('INT','BOOL','AUTOINT','F32','FILENAME','VEC3','RGBA','CONDRGB')}
 for name,line in macros.items():extension=re.sub(r'^#define TOK_'+name+r'\([^\n]+',lambda m:line,extension,flags=re.M)
