 code=code.replace('case TOK_START:case TOK_END:return(CrcHandler)','case TOK_IGNORE:case TOK_START:case TOK_END:return(CrcHandler)').replace('case TOK_BOOL_X:case TOK_INT_X:','case TOK_CONDRGB_X:case TOK_U8_X:case TOK_BOOL_X:case TOK_INT_X:').replace('case TOK_CURRENTFILE_X:case TOK_STRING_X:return(CrcHandler)','case TOK_FILENAME_X:case TOK_CURRENTFILE_X:case TOK_STRING_X:return(CrcHandler)')
 code+='\n'+extension
 dictionary=re.search(r'typedef struct PowerDictionary\s*\{.*?} PowerDictionary;',texts['Common/entity/powers.h'],re.S).group();table=re.search(r'TokenizerParseInfo ParsePowerDictionary\[\]\s*=.*?\n};',source,re.S).group();pins['PowerDictionary']=sha(dictionary);pins['ParsePowerDictionary']=sha(table);code+='\n'+dictionary+'\n'+table+'\nunsigned original_power_schema_crc(unsigned with_defines){return ParseTableCRC(ParsePowerDictionary,with_defines?g_pParsePowerDefines:NULL);}\n'
 dispatch={}
