  matched=re.search(r'\{\s*'+token+r',.*?\b(\w+_interpretfield),',internals,re.S);assert matched.group(1)==handler,(token,matched.group(1),handler);block=matched.group();dispatch[token]={'handler':handler,'source_prefix_sha256_lf':sha(block)}
