 tables=['ParsePowerDictionary','ParseBasePower','ParseAttribModTemplate','ParseSuppressPair','ParsePowerVar','ParsePowerCustomFX'];enums=['BoolEnum']+enum_names+['ParsePowerDefines'];code+='\nstatic ParseTable*power_schema_tables[]={'+','.join(tables)+'};\nstatic StaticDefine*power_schema_enums[]={'+','.join('(StaticDefine*)'+n for n in enums)+'};\n'
